package com.example.ui.components

import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.PathParser
import androidx.compose.ui.unit.dp

/**
 * Authentic Apple SF Symbols icons from icons.zip.
 * Vectorized on a uniform 16x16 optical grid so each symbol preserves its exact native aspect ratio and relative size.
 */
object LucideIcons {

    private fun sfIcon(
        name: String,
        glyphW: Float,
        glyphH: Float,
        pathData: String,
        canvasSize: Float = 16f
    ): ImageVector {
        val dx = (canvasSize - glyphW) / 2f
        val dy = (canvasSize - glyphH) / 2f
        return ImageVector.Builder(
            name = name,
            defaultWidth = 24.dp,
            defaultHeight = 24.dp,
            viewportWidth = canvasSize,
            viewportHeight = canvasSize
        ).addGroup(
            translationX = dx,
            translationY = dy
        ).addPath(
            pathData = PathParser().parsePathString(pathData).toNodes(),
            fill = SolidColor(Color.White)
        ).clearGroup().build()
    }

